/** === AUTO CLEANING MODULE (SAFE FORMATTING VERSION) === */
function runAutoClean() {
  const sheet = SpreadsheetApp.getActiveSheet();
  createBackup(sheet, "AutoClean");

  const range = sheet.getDataRange();
  const values = range.getValues();
  const headers = values[0].map(h => h.toString().trim());
  const cleaned = [headers];
  const seenRows = new Set();

  for (let i = 1; i < values.length; i++) {
    let row = values[i].map(v => (typeof v === 'string' ? v.trim() : v));

    // --- Header-aware formatting ---
    for (let j = 0; j < row.length; j++) {
      const header = headers[j].toLowerCase();
      const cell = row[j];
      if (isDateHeader(header)) {
        row[j] = formatDateCell(cell); // format only
      } else if (isTimeHeader(header)) {
        row[j] = formatTimeCell(cell); // format only
      }
    }

    // Skip empty rows
    if (row.every(v => v === "")) continue;

    const rowKey = JSON.stringify(row);
    if (!seenRows.has(rowKey)) {
      seenRows.add(rowKey);
      cleaned.push(row);
    }
  }

  range.clearContent();
  sheet.getRange(1, 1, cleaned.length, cleaned[0].length).setValues(cleaned);
  SpreadsheetApp.getUi().alert('✅ Sheet cleaned and formatted safely!');
}

/** Trims only spaces in the active selection */
function trimSelectionSides() {
  const range = SpreadsheetApp.getActiveRange();
  if (!range) return;
  const values = range.getValues();
  const trimmed = values.map(r => r.map(v => (typeof v === 'string' ? v.trim() : v)));
  range.setValues(trimmed);
}

/** Removes duplicate rows (based on all columns) */
function removeDuplicates() {
  const sheet = SpreadsheetApp.getActiveSheet();
  createBackup(sheet, "RemoveDuplicates");

  const range = sheet.getDataRange();
  const values = range.getValues();
  const headers = values.shift();

  const unique = [];
  const seen = new Set();
  for (const row of values) {
    const key = JSON.stringify(row);
    if (!seen.has(key)) {
      seen.add(key);
      unique.push(row);
    }
  }

  const cleaned = [headers, ...unique];
  range.clearContent();
  sheet.getRange(1, 1, cleaned.length, cleaned[0].length).setValues(cleaned);
  SpreadsheetApp.getUi().alert(`✅ Removed duplicates — kept ${unique.length} unique rows.`);
}

/** Normalizes date/time formats across the sheet (explicit user action only) */
function normalizeDateTime() {
  const sheet = SpreadsheetApp.getActiveSheet();
  createBackup(sheet, "NormalizeDateTime");

  const range = sheet.getDataRange();
  const values = range.getValues();
  const headers = values[0].map(h => h.toString().trim().toLowerCase());

  for (let i = 1; i < values.length; i++) {
    for (let j = 0; j < values[i].length; j++) {
      const header = headers[j];
      const val = values[i][j];
      if (val === "" || val === null || val === undefined) continue;

      if (isDateHeader(header)) {
        values[i][j] = formatDateCell(val);
      } else if (isTimeHeader(header)) {
        values[i][j] = formatTimeCell(val);
      }
    }
  }

  range.setValues(values);
  SpreadsheetApp.getUi().alert('✅ Dates & times formatted (no values changed).');
}

/** --- Detects whether a header likely represents a date column --- */
function isDateHeader(header) {
  const dateKeywords = [
    "date", "day", "dob", "birth", "created", "joined",
    "processed", "updated", "submitted", "timestamp"
  ];
  const skipKeywords = [
    "amount", "price", "balance", "total", "cost",
    "fare", "qty", "quantity", "account", "id", "number"
  ];
  return dateKeywords.some(k => header.includes(k)) && !skipKeywords.some(k => header.includes(k));
}

/** --- Detects whether a header likely represents a time column --- */
function isTimeHeader(header) {
  const timeKeywords = ["time", "hour", "duration", "clock", "timing"];
  return timeKeywords.some(k => header.includes(k));
}

/** --- Format a date value safely (no reinterpretation) --- */
function formatDateCell(val) {
  try {
    if (!val) return val;

    // If it's a true Date object
    if (Object.prototype.toString.call(val) === '[object Date]' && !isNaN(val)) {
      return Utilities.formatDate(val, Session.getScriptTimeZone(), 'dd/MM/yyyy');
    }

    // If it's numeric serial (Excel/Sheets style)
    if (typeof val === 'number' && val > 25000 && val < 60000) {
      const d = new Date(Math.round((val - 25569) * 86400 * 1000));
      if (!isNaN(d)) return Utilities.formatDate(d, Session.getScriptTimeZone(), 'dd/MM/yyyy');
    }

    // If it's a string, only normalize *formatting*, not meaning
    if (typeof val === 'string') {
      const trimmed = val.trim();

      // Match recognizable short date forms like 1/1/24 → pad to 01/01/2024
      const shortPattern = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/;
      const m = trimmed.match(shortPattern);
      if (m) {
        let [_, d, mth, y] = m;
        if (y.length === 2) y = '20' + y; // assume 20xx if 2-digit year
        return `${d.padStart(2, '0')}/${mth.padStart(2, '0')}/${y}`;
      }
      return trimmed;
    }

    return val;
  } catch (e) {
    Logger.log("formatDateCell() error for " + val + ": " + e.message);
    return val;
  }
}

/** --- Format a time value safely (no reinterpretation) --- */
function formatTimeCell(val) {
  try {
    if (!val) return val;

    // If numeric fraction of a day (Sheets style)
    if (typeof val === 'number' && val >= 0 && val < 1) {
      const totalSeconds = Math.round(val * 24 * 60 * 60);
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;
      return [hours, minutes, seconds].map(v => v.toString().padStart(2, '0')).join(':');
    }

    // If string, format to HH:MM:SS
    if (typeof val === 'string') {
      const str = val.trim();
      const timePattern = /^(\d{1,2})([:\-])?(\d{0,2})?([:\-]?(\d{0,2}))?$/;
      const m = str.match(timePattern);
      if (m) {
        const h = m[1].padStart(2, '0');
        const mi = (m[3] || '00').padStart(2, '0');
        const s = (m[5] || '00').padStart(2, '0');
        return `${h}:${mi}:${s}`;
      }
    }

    return val;
  } catch (e) {
    Logger.log("formatTimeCell() error for " + val + ": " + e.message);
    return val;
  }
}

/** --- Backup utility --- */
function createBackup(sheet, tag) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const name = sheet.getName();
  const backupName = `Backup_${name}_${tag}_${new Date().toISOString().replace(/[:.]/g, '-')}`;
  const newSheet = sheet.copyTo(ss);
  newSheet.setName(backupName);
  newSheet.hideSheet();
  Logger.log(`🧷 Backup created: ${backupName}`);
}

/** --- Restore the latest backup for current sheet --- */
function restoreLatestBackup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();
  const sheetName = sheet.getName();
  const allSheets = ss.getSheets();

  const backups = allSheets
    .map(s => s.getName())
    .filter(n => n.startsWith(`Backup_${sheetName}_`));

  if (backups.length === 0) {
    SpreadsheetApp.getUi().alert('⚠️ No backups found for this sheet.');
    return;
  }

  backups.sort((a, b) => a.localeCompare(b));
  const latestName = backups[backups.length - 1];
  const backupSheet = ss.getSheetByName(latestName);
  if (!backupSheet) {
    SpreadsheetApp.getUi().alert('⚠️ Backup sheet could not be found.');
    return;
  }

  const data = backupSheet.getDataRange().getValues();

  const confirm = SpreadsheetApp.getUi().alert(
    'Restore Backup',
    `This will overwrite current sheet "${sheetName}" with data from "${latestName}". Continue?`,
    SpreadsheetApp.getUi().ButtonSet.YES_NO
  );

  if (confirm !== SpreadsheetApp.getUi().Button.YES) return;

  sheet.clearContents();
  sheet.getRange(1, 1, data.length, data[0].length).setValues(data);
  SpreadsheetApp.getUi().alert(`✅ Restored data from: ${latestName}`);
}

/**
 * @fileoverview Contains functions for the Regex Sidebar, including
 * the core execution logic and pattern storage using PropertiesService.
 */

// ----------------------------------------------------------------------
// UTILITY FUNCTIONS (Implemented from placeholders)
// ----------------------------------------------------------------------

/**
 * Creates a simple backup sheet by duplicating the current sheet.
 * NOTE: This is a robust safety feature before destructive operations.
 * @param {GoogleAppsScript.Spreadsheet.Sheet} sheet The active sheet.
 * @param {string} action Description of the action causing the backup.
 */
function createBackup(sheet, action) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  // Create a uniquely named backup sheet
  const backupSheetName = sheet.getName() + ' Backup (' + action + ') ' + new Date().toLocaleTimeString();
  sheet.copyTo(ss).setName(backupSheetName);
  Logger.log("Created backup sheet: " + backupSheetName);
}

/**
 * Logs the successful regex action configuration to User Properties.
 * This log is retrieved by the viewLogs() function in SidebarUI.gs.
 * @param {object} config The configuration object passed to runRegexAction.
 */
function logAction(config) {
  const properties = PropertiesService.getUserProperties();
  const logKey = 'REGEX_ACTION_LOGS'; // Key must match SidebarUI.gs > getLogs()

  // Load existing logs or initialize an empty array
  const logs = JSON.parse(properties.getProperty(logKey) || '[]');

  const logEntry = {
    timestamp: new Date().toLocaleString(),
    pattern: config.pattern,
    action: config.action,
    replacement: config.replacement,
    flags: config.flags,
    outputMode: config.outputMode
  };

  // Add new entry to the start of the array (most recent first)
  logs.unshift(logEntry);

  // Limit the log size to prevent property storage limits (e.g., last 50 entries)
  while (logs.length > 50) {
    logs.pop(); 
  }

  // Save the updated log array
  properties.setProperty(logKey, JSON.stringify(logs));
  Logger.log("Logged regex action: " + JSON.stringify(logEntry));
}

// ----------------------------------------------------------------------
// CORE REGEX EXECUTION
// ----------------------------------------------------------------------

function runRegexAction(config) {
  const { pattern, action, replacement, flags, preview, outputMode } = config;
  const sheet = SpreadsheetApp.getActiveSheet();
  const range = sheet.getActiveRange();
  const values = range.getValues();

  // === Preserve formatting before any changes ===
  const backgrounds = range.getBackgrounds();
  const fontColors = range.getFontColors();
  const fontWeights = range.getFontWeights();

  // --- Always clear old highlights ---
  range.setBackground(null);

  // --- Create safety backup before applying any changes ---
  if (!preview && ['replace', 'newColumn', 'newSheet'].includes(outputMode)) {
    createBackup(sheet, "RegexRun");
  }

  // Use try-catch to safely handle invalid regex patterns
  let regex;
  try {
    regex = new RegExp(pattern, flags || 'g');
  } catch (e) {
    // If the regex is invalid, return an error message to the client
    return { error: true, message: "Invalid Regular Expression: " + e.message };
  }

  const output = []; // 2D array for final output
  const previewResults = []; // 2D array for preview

  for (let r = 0; r < values.length; r++) {
    const row = values[r];
    const newRow = []; // Array for current output row
    const previewRow = []; // Array for current preview row

    for (let c = 0; c < row.length; c++) {
      let cell = row[c];

      // Convert non-strings to string for regex matching
      const cellString = String(cell);

      let newCellValue = cell; // Default value if no change
      let previewCellValue = cell;

      if (typeof cellString === 'string') {

        // --- Highlighting (Needs separate regex instance for highlighting) ---
        // Use a temporary regex instance for test/highlighting
        let highlightRegex = new RegExp(pattern, flags || 'g');
        const matched = highlightRegex.test(cellString);

        if (matched) {
          range.getCell(r + 1, c + 1).setBackground('#FFF59D');
        }

        // --- Action Logic ---
        if (action === 'extract') {
          // Extraction: Find all matches or just the first match (depends on 'g' flag)
          // We must use a fresh matchAll call since test() consumes the match state
          const matchAllRegex = new RegExp(pattern, flags || 'g');
          const matches = [...cellString.matchAll(matchAllRegex)].map(m => m[0]);
          if (matches.length > 0) {
            newCellValue = matches.join(', '); // Join multiple matches
            previewCellValue = newCellValue;
          } else {
            newCellValue = '';
            previewCellValue = '';
          }
        } else if (action === 'replace') {
          // Replacement uses the original regex instance
          const replaced = cellString.replace(regex, replacement);
          previewCellValue = replaced;
          newCellValue = replaced;
        } else if (action === 'test') {
          // Re-test to get the true/false result after the highlighting test consumed it
          const testRegex = new RegExp(pattern, flags);
          const testResult = testRegex.test(cellString);
          previewCellValue = testResult; // true/false
          newCellValue = testResult;
        } else {
          // Default to original cell value
        }
      }

      newRow.push(newCellValue);
      previewRow.push(previewCellValue);
    }

    // Add the processed row to the 2D output arrays
    output.push(newRow);
    previewResults.push(previewRow);
  }

  if (preview) return previewResults;

  // --- Apply Changes based on Output Mode ---
  if (outputMode === 'replace') {
    range.setValues(output);

    // === Restore original formatting ===
    range.setBackgrounds(backgrounds);
    range.setFontColors(fontColors);
    range.setFontWeights(fontWeights);

  } else if (outputMode === 'newColumn') {
    const startCol = range.getLastColumn() + 1;
    // output is a 2D array, so we use its dimensions
    sheet.getRange(range.getRow(), startCol, output.length, output[0].length).setValues(output);
  } else if (outputMode === 'newSheet') {
    const newSheet = SpreadsheetApp.getActiveSpreadsheet().insertSheet('RegexOutput_' + new Date().getTime());
    newSheet.getRange(1, 1, output.length, output[0].length).setValues(output);
  }

  // Log successful action only if it was executed (not preview)
  logAction(config);
  return 'done';
}


// ----------------------------------------------------------------------
// PATTERN STORAGE FUNCTIONS
// ----------------------------------------------------------------------

const PROPERTIES_KEY = 'SAVED_REGEX_PATTERNS';

/**
 * Loads all user-saved regex patterns from the PropertiesService.
 * @returns {object} An object mapping pattern names to their configuration.
 */
function loadPatterns() {
  const properties = PropertiesService.getUserProperties();
  const rawData = properties.getProperty(PROPERTIES_KEY);
  // Returns an empty object if no patterns are found
  return rawData ? JSON.parse(rawData) : {};
}

/**
 * Saves a new regex pattern configuration.
 * @param {string} name - The name to save the pattern under.
 * @param {string} pattern - The regex pattern string.
 * @param {string} action - The action (e.g., 'extract', 'replace').
 * @param {string} replacement - The replacement string.
 * @param {string} flags - The regex flags (e.g., 'gi').
 * @returns {void}
 */
function savePattern(name, pattern, action, replacement, flags) {
  const properties = PropertiesService.getUserProperties();
  const patterns = loadPatterns();

  patterns[name] = {
    pattern: pattern,
    action: action,
    replacement: replacement,
    flags: flags
  };

  properties.setProperty(PROPERTIES_KEY, JSON.stringify(patterns));
}

// ----------------------------------------------------------------------
// SIDEBAR & LOGS ENTRYPOINTS (Needed for bound script + menu to work)
// ----------------------------------------------------------------------

/**
 * Opens the Regex Sidebar UI inside the sheet.
 */
function openRegexSidebar() {
  const html = HtmlService.createHtmlOutputFromFile('Sidebar')
    .setTitle('Advanced Regex Tool');
  SpreadsheetApp.getUi().showSidebar(html);
}

/**
 * Opens a simple alert letting the user know where to find logs.
 * (Optional: could later show a proper log viewer sidebar)
 */
function viewLogs() {
  const ui = SpreadsheetApp.getUi();
  const logKey = 'REGEX_ACTION_LOGS';
  const props = PropertiesService.getUserProperties();
  const logs = JSON.parse(props.getProperty(logKey) || '[]');
  if (logs.length === 0) {
    ui.alert('No regex logs found yet.');
    return;
  }
  ui.alert(`📘 You have ${logs.length} logged Regex actions. Viewable in the Script Properties.`);
}

/** === COMPARISON TOOL ===
 * Creates a side-by-side comparison sheet for current sheet vs a chosen backup sheet.
 * Highlights:
 *  🔴 Red → value mismatch
 *  🟡 Yellow → extra rows or columns found only in one sheet
 */
function compareWithBackup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const ui = SpreadsheetApp.getUi();
  const parentSheet = ss.getActiveSheet();
  const parentName = parentSheet.getName();

  // --- Step 1: Ask user which backup to compare ---
  const backups = ss.getSheets()
    .map(s => s.getName())
    .filter(name => {
      const n = name.toLowerCase();
      const parent = parentName.toLowerCase();

      // Old style: "Backup_<Parent>_yyyy..."
      if (n.startsWith(`backup_${parent}_`)) return true;

      // Newer style examples: "Data Backup (AutoClean) 10:43:04"
      if (n.includes('backup') && n.includes(parent)) return true;

      // Generic data backups
      if (n.includes('data backup')) return true;

      return false;
    });

  const choice = ui.prompt(
    "Compare with Backup",
    "Available backups:\n" + backups.join("\n") +
      "\n\nEnter exact name of the backup sheet to compare:",
    ui.ButtonSet.OK_CANCEL
  );

  if (choice.getSelectedButton() !== ui.Button.OK) return;
  const backupName = choice.getResponseText().trim();
  const backupSheet = ss.getSheetByName(backupName);
  if (!backupSheet) {
    ui.alert("⚠️ Backup sheet not found: " + backupName);
    return;
  }

  // --- Step 2: Prepare data ---
  const parentData = parentSheet.getDataRange().getValues();
  const backupData = backupSheet.getDataRange().getValues();

  const parentHeaders = parentData[0].map(h => h.toString().trim());
  const backupHeaders = backupData[0].map(h => h.toString().trim());

  // --- Step 3: Determine column structure ---
  const allHeaders = Array.from(new Set([...backupHeaders, ...parentHeaders]));
  const extraParentCols = parentHeaders.filter(h => !backupHeaders.includes(h));
  const extraBackupCols = backupHeaders.filter(h => !parentHeaders.includes(h));

  const orderedHeaders = [
    ...allHeaders.filter(h => backupHeaders.includes(h) && parentHeaders.includes(h)),
    ...extraParentCols,
    ...extraBackupCols
  ];

  // --- Step 4: Create comparison sheet ---
  const compName = `Comparison_${parentName}_vs_${backupName}`;
  const oldComp = ss.getSheetByName(compName);
  if (oldComp) ss.deleteSheet(oldComp);

  const compSheet = ss.insertSheet(compName);
  compSheet.activate();

  // --- Step 5: Write headers (Backup–Current pairs) ---
  const pairedHeaders = [];
  orderedHeaders.forEach(h => {
    pairedHeaders.push(`${h} (Backup)`);
    pairedHeaders.push(`${h} (Current)`);
  });
  compSheet.getRange(1, 1, 1, pairedHeaders.length)
    .setValues([pairedHeaders])
    .setFontWeight("bold")
    .setBackground("#f3f3f3");

  // --- Step 6: Compare row by row ---
  const maxRows = Math.max(parentData.length, backupData.length) - 1; // exclude header
  const comparison = [];
  const backupBody = backupData.slice(1);
  const parentBody = parentData.slice(1);

  for (let i = 0; i < maxRows; i++) {
    const backupRow = backupBody[i] || [];
    const parentRow = parentBody[i] || [];
    const backupMap = {};
    const parentMap = {};

    orderedHeaders.forEach((h) => {
      const bi = backupHeaders.indexOf(h);
      const pi = parentHeaders.indexOf(h);
      backupMap[h] = bi >= 0 ? backupRow[bi] : "";
      parentMap[h] = pi >= 0 ? parentRow[pi] : "";
    });

    const rowOut = [];
    orderedHeaders.forEach(h => {
      rowOut.push(backupMap[h]);
      rowOut.push(parentMap[h]);
    });
    comparison.push(rowOut);
  }

  // --- Step 7: Paste data ---
  if (comparison.length > 0)
    compSheet.getRange(2, 1, comparison.length, pairedHeaders.length).setValues(comparison);

  // --- Step 8: Highlight discrepancies & extras ---
  const lastRow = compSheet.getLastRow();
  const lastCol = compSheet.getLastColumn();
  const range = compSheet.getRange(2, 1, lastRow - 1, lastCol);
  const bgColors = range.getBackgrounds();
  const values = range.getValues();

  // 🔹 Helper: fuzzy equality for date/time precision issues
  function isNearlyEqual(a, b) {
    if (a === b) return true;
    if (a == null || b == null || a === "" || b === "") return a === b;

    // numeric (for serial dates/times)
    if (typeof a === "number" && typeof b === "number") {
      return Math.abs(a - b) < 0.0001;
    }

    // both are valid Date objects
    if (a instanceof Date && b instanceof Date) {
      return Math.abs(a.getTime() - b.getTime()) < 1000; // within 1s tolerance
    }

    return false;
  }

  // Compare every Backup–Current pair
  for (let r = 0; r < values.length; r++) {
    for (let c = 0; c < pairedHeaders.length; c += 2) {
      const backupVal = values[r][c];
      const parentVal = values[r][c + 1];

      // Apply tolerance for date/time precision only
      if (!isNearlyEqual(backupVal, parentVal)) {
        bgColors[r][c] = "#ffb3b3";     // light red
        bgColors[r][c + 1] = "#ffb3b3"; // light red
      }
    }
  }

  // Highlight extra columns
  const yellow = "#fff3b3";
  orderedHeaders.forEach((h, i) => {
    const backupCol = 2 * i + 1;
    const currentCol = 2 * i + 2;
    if (extraParentCols.includes(h)) {
      compSheet.getRange(1, currentCol, lastRow).setBackground(yellow);
    }
    if (extraBackupCols.includes(h)) {
      compSheet.getRange(1, backupCol, lastRow).setBackground(yellow);
    }
  });

  // Highlight extra rows
  if (parentBody.length > backupBody.length) {
    compSheet.getRange(backupBody.length + 2, 1, parentBody.length - backupBody.length, lastCol)
      .setBackground(yellow);
  }

  range.setBackgrounds(bgColors);
  ui.alert(`✅ Comparison sheet created:\n"${compName}"\n🔴 Red = Mismatch | 🟡 Yellow = New/Extra`);
}
